import type { BankItem, Difficulty } from './types';

/**
 * Banque de questions de français (lecture et langue) pour les élèves de
 * 4e, 5e et 6e année (2e et 3e cycle du primaire au Québec, Progression des
 * apprentissages en français; programmes de français du CSAP en
 * Nouvelle-Écosse).
 *
 * Difficulté = année scolaire : 1 = 4e année, 2 = 5e année, 3 = 6e année.
 * Mêmes sujets que READING_BANK_FR (readingBankFr.ts), sauf « fr-sons » :
 * on n'enseigne plus les sons à ces années.
 */

function q(
  topic: string,
  difficulty: Difficulty,
  prompt: string,
  answer: string,
  wrong: string[],
  explanation: string,
): BankItem {
  return { topic, difficulty, prompt, answer, wrong, explanation };
}

